"""Top-level orchestration: config, aliases, rewrite, parse, resolve, validate, run."""

import os
import sys
import time

from . import config_loader
from .arguments import END_OF_OPTIONS, is_assoc_token, parse_argv
from .commands import build_command_tree
from .context import Context
from .errors import AppctlError, MultiLineError, UsageError
from .help import render_root_help, render_usage
from .logger import FileLogger, log_path
from .output import Output
from .remote import run_remote
from .resolver import resolve
from .rewrites import apply_rewrites
from .runtime_config import build_runtime_config, deprecation_warnings, is_strict_mode
from .suggest import get_suggestion
from .validator import ArgumentValidator


def extract_alias(argv):
    """Return ``(alias, argv_without_alias)``; the alias is the first non-flag token."""
    for index, token in enumerate(argv):
        if token == END_OF_OPTIONS:
            break
        if is_assoc_token(token):
            continue
        if config_loader.is_alias(token):
            return token, argv[:index] + argv[index + 1:]
        break
    return None, list(argv)


def _unique(items):
    seen = []
    for item in items:
        if item not in seen:
            seen.append(item)
    return seen


def check_disabled(command, typed, disabled):
    """Raise if the command or one of its parents is disabled."""
    disabled = {" ".join(str(entry).split()) for entry in disabled}
    for path in (command.path, typed[:len(command.path)]):
        for depth in range(1, len(path) + 1):
            name = " ".join(path[:depth])
            if name in disabled:
                raise AppctlError(f"The '{name}' command has been disabled.")


def guarded(output, action, *args):
    """Run ``action`` and report user-facing errors; return the exit code."""
    try:
        return int(action(*args) or 0)
    except UsageError as exc:
        output.line(exc.usage)
        return exc.exit_code
    except MultiLineError as exc:
        output.error_multi_line(exc.lines, sensitive=exc.sensitive)
        return exc.exit_code
    except AppctlError as exc:
        output.error(exc.message, sensitive=exc.sensitive)
        return exc.exit_code


def is_completion_request(positional):
    """Tab completion runs ``cli completions``; it is never logged."""
    return list(positional[:2]) == ["cli", "completions"]


class Runner:
    def __init__(self, argv, parsed, environ, output, strict, loaded):
        self.argv = argv
        self.parsed = parsed
        self.environ = environ
        self.output = output
        self.strict = strict
        self.loaded = loaded
        self._root = None

    @property
    def root(self):
        if self._root is None:
            self._root = build_command_tree()
        return self._root

    # -- aliases ----------------------------------------------------------

    def run_alias(self, name, stack=()):
        aliases = self.loaded.aliases
        if name == config_loader.ALL_ALIAS and not aliases:
            raise AppctlError("Cannot use '@all' when no aliases are registered.")
        if name not in aliases:
            message = f"Alias '{name}' not found."
            suggestion = get_suggestion(name, list(aliases))
            if suggestion:
                message += f"\nDid you mean '{suggestion}'?"
            raise AppctlError(message)
        definition = aliases[name]
        if name == config_loader.ALL_ALIAS and definition is None:
            members = sorted((a for a, d in aliases.items() if a != name and not isinstance(d, list)),
                             key=config_loader.alias_sort_key)
            return self.run_group(name, members, stack)
        if isinstance(definition, list):
            members = _unique(definition)
            invalid = [m for m in members if m not in aliases]
            if invalid:
                raise AppctlError(
                    f"Group '{name}' contains one or more invalid aliases: {', '.join(invalid)}."
                )
            return self.run_group(name, members, stack)
        return self.run(name, definition if isinstance(definition, dict) else {})

    def run_group(self, name, members, stack):
        stack = stack + (name,)
        result = 0
        for member in members:
            if member in stack:
                continue
            self.output.log(member)
            self.output.stdout.flush()
            code = guarded(self.output, self.run_alias, member, stack)
            self.output.stdout.flush()
            if code:
                result = code
        return result

    # -- a single execution ----------------------------------------------

    def run(self, alias=None, alias_params=None):
        runtime = build_runtime_config(self.parsed.runtime, self.loaded.merged, alias_params)
        self.output.set_color(runtime.get("color"))
        if runtime.get("ssh"):
            return run_remote(runtime["ssh"], self.argv, self.environ, self.output,
                              alias=alias, alias_params=alias_params,
                              skip_tty=bool(runtime.get("skip-tty")))
        positional = self.parsed.positional
        if not positional:
            self.output.line(render_root_help(self.root))
            return 0
        command, remaining = resolve(self.root, positional)
        check_disabled(command, positional, runtime["disabled_commands"])
        if not command.is_runnable:
            self.output.line(render_usage(command))
            return 0
        self.output.debug(f"Running command: {command.full_name}")
        args, assoc = ArgumentValidator(command).validate(
            remaining, self.parsed.assoc, warn=self.output.warning,
            read_stdin=self.output.read_stdin,
        )
        context = Context(root=self.root, command=command, output=self.output,
                          runtime=runtime, strict=self.strict, config=self.loaded,
                          alias=alias)
        return command.handler(context, args, assoc)


def main(argv=None, environ=None, stdout=None, stderr=None, cwd=None, stdin=None):
    started = time.monotonic()
    argv = sys.argv[1:] if argv is None else list(argv)
    environ = os.environ if environ is None else environ
    strict = is_strict_mode(environ)

    invocation = list(argv)
    alias, argv = extract_alias(argv)
    parsed = parse_argv(apply_rewrites(argv), strict=strict)
    logger = FileLogger(log_path(config_loader.root_dir(environ)),
                        enabled=not is_completion_request(parsed.positional))
    logger.start_invocation(invocation)
    output = Output(quiet=bool(parsed.runtime.get("quiet")), debug=parsed.runtime.get("debug", False),
                    stdout=stdout, stderr=stderr, stdin=stdin,
                    color=parsed.runtime.get("color", "auto"), logger=logger, start_time=started)
    for warning in deprecation_warnings(parsed.runtime):
        print(warning, file=output.stderr)

    def start():
        loaded = config_loader.load(environ, cwd)
        output.set_color(build_runtime_config(parsed.runtime, loaded.merged)["color"])
        output.debug(f"Using global config: {loaded.global_path}", group="bootstrap")
        if loaded.project_path:
            output.debug(f"Using project config: {loaded.project_path}", group="bootstrap")
        else:
            output.debug("No project config found.", group="bootstrap")
        runner = Runner(argv, parsed, environ, output, strict, loaded)
        if alias:
            return runner.run_alias(alias)
        return runner.run()

    return guarded(output, start)
"""Append-only file log of every invocation at ``<root>/logs/appctl.log``."""

import os
import re
import shlex
from datetime import datetime, timezone

from . import PROGRAM_NAME

LOG_DIR = "logs"
LOG_FILE = f"{PROGRAM_NAME}.log"
DELIMITER = "-" * 72
REDACTED = "[REDACTED]"

# ``--key=value`` arguments whose value must never reach the disk.
SENSITIVE_KEY_RE = re.compile(r"pass|pwd|secret|token|api[-_]?key|private[-_]?key|auth|credential",
                              re.IGNORECASE)


def log_path(root_dir):
    return os.path.join(root_dir, LOG_DIR, LOG_FILE)


def utc_timestamp(now=None):
    """ISO 8601 UTC timestamp with second precision, e.g. ``2024-01-31T12:00:00Z``."""
    now = now or datetime.now(timezone.utc)
    return now.astimezone(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")


def redact_argv(argv):
    """Replace the values of sensitive ``--key=value`` arguments."""
    redacted = []
    for index, token in enumerate(argv):
        if token == "--":
            redacted.extend(argv[index:])
            break
        if token.startswith("--") and "=" in token:
            key = token[2:].split("=", 1)[0]
            if SENSITIVE_KEY_RE.search(key):
                token = f"--{key}={REDACTED}"
        redacted.append(token)
    return redacted


class FileLogger:
    """Writes timestamped entries; write failures silently disable logging."""

    def __init__(self, path, enabled=True):
        self.path = path
        self.enabled = bool(enabled and path)

    def start_invocation(self, argv):
        """Write the delimiter line and the (redacted) command line."""
        command = shlex.join([PROGRAM_NAME] + redact_argv(list(argv)))
        self._append(f"{DELIMITER}\n[{utc_timestamp()}] Command: {command}\n")

    def write(self, text):
        """Append one entry; every line of it carries the timestamp."""
        stamp = utc_timestamp()
        self._append("".join(f"[{stamp}] {line}\n" for line in str(text).split("\n")))

    def _append(self, data):
        if not self.enabled:
            return
        try:
            directory = os.path.dirname(self.path)
            if directory:
                os.makedirs(directory, exist_ok=True)
            with open(self.path, "a", encoding="utf-8") as handle:
                handle.write(data)
        except OSError:
            self.enabled = False
"""Exception types used to signal user-facing failures."""


class AppctlError(Exception):
    """A fatal error reported as ``Error: <message>`` on STDERR.

    A ``sensitive`` error carries user-supplied material and is never
    persisted to the log file.
    """

    def __init__(self, message, exit_code=1, sensitive=False):
        super().__init__(message)
        self.message = message
        self.exit_code = exit_code
        self.sensitive = sensitive


class MultiLineError(AppctlError):
    """A fatal error whose lines are shown in a highlighted box."""

    def __init__(self, lines, exit_code=1, sensitive=False):
        self.lines = [str(line) for line in lines]
        super().__init__("\n".join(self.lines), exit_code, sensitive)


class CommandNotFoundError(AppctlError):
    """Raised when a command or subcommand cannot be resolved."""


class UsageError(AppctlError):
    """Raised when a command must print its usage on STDOUT and fail."""

    def __init__(self, usage, exit_code=1):
        super().__init__(usage, exit_code)
        self.usage = usage


class SynopsisError(ValueError):
    """Raised when a command is registered with a malformed synopsis."""
"""Global runtime configuration parameters."""

import copy
from dataclasses import dataclass

STRICT_ARGS_ENV = "APPCTL_STRICT_ARGS_MODE"


@dataclass(frozen=True)
class GlobalParameter:
    name: str
    synopsis: str
    description: str
    default: object = None
    runtime: bool = True
    file: bool = True
    multiple: bool = False
    deprecated: str = None
    hidden: bool = False


def _file_only(name, description, default=None):
    return GlobalParameter(name, "", description, default, runtime=False, file=True)


GLOBAL_PARAMETERS = {
    p.name: p
    for p in (
        GlobalParameter("path", "--path=<path>", "Path to the application files.", None),
        GlobalParameter("url", "--url=<url>", "Pretend request came from given URL.", None),
        GlobalParameter("ssh", "--ssh=<[scheme:][user@]host|container>[:port][path]",
                        "Perform operation against a remote server over SSH.", None),
        GlobalParameter("http", "--http=<http>", "Perform operation against a remote install over HTTP.", None),
        GlobalParameter("user", "--user=<id|login|email>", "Set the user for the current request.", None),
        GlobalParameter("skip-plugins", "--skip-plugins[=<plugins>]", "Skip loading all or some plugins.", False),
        GlobalParameter("skip-themes", "--skip-themes[=<themes>]", "Skip loading all or some themes.", False),
        GlobalParameter("skip-packages", "--skip-packages", "Skip loading all installed packages.", False),
        GlobalParameter("require", "--require=<path>", "Load a file before running the command.", None),
        GlobalParameter("exec", "--exec=<php-code>", "Execute code before running the command.", None),
        GlobalParameter("context", "--context=<context>", "Load the application in a given context.", "cli"),
        _file_only("disabled_commands", "(Sub)commands to disable.", []),
        _file_only("projects_path", "Path where projects are stored."),
        _file_only("locale", "Locale to use.", "en_US"),
        _file_only("cert-email", "Email address used for certificate registration."),
        _file_only("env", "Environment the tool runs in."),
        _file_only("admin-email", "Email address of the administrator."),
        _file_only("sysctl", "Kernel parameters applied to containers."),
        _file_only("skip-tty", "Never allocate a TTY for remote commands.", False),
        _file_only("custom-compose", "Path to a custom compose file."),
        _file_only("installer_version", "Release channel of the installer.", "stable"),
        GlobalParameter("color", "--[no-]color", "Whether to colorize the output.", "auto"),
        GlobalParameter("debug", "--debug[=<group>]", "Show all errors and debug messages.", False,
                        file=False),
        GlobalParameter("prompt", "--prompt[=<assoc>]", "Prompt the user to enter values for all arguments.",
                        False, file=False),
        GlobalParameter("quiet", "--quiet", "Suppress informational messages.", False, file=False),
    )
}


def is_global_parameter(key):
    """True for global parameters that may be given as runtime flags."""
    param = GLOBAL_PARAMETERS.get(key)
    return param is not None and param.runtime


def is_file_parameter(key):
    param = GLOBAL_PARAMETERS.get(key)
    return param is not None and param.file


def visible_parameters():
    """Global parameters that may be shown in help output."""
    return {name: p for name, p in GLOBAL_PARAMETERS.items() if not p.hidden}


def deprecation_warnings(supplied):
    """Warning lines for every deprecated parameter used as a runtime flag."""
    return [
        f"Warning: The --{key} global parameter is deprecated."
        for key in supplied
        if key in GLOBAL_PARAMETERS and GLOBAL_PARAMETERS[key].deprecated is not None
    ]


def is_strict_mode(environ):
    return bool(environ.get(STRICT_ARGS_ENV))


def _arrayify(value):
    if value is None:
        return []
    return list(value) if isinstance(value, (list, tuple)) else [value]


def build_runtime_config(supplied, *layers):
    """Merge configuration over the defaults.

    ``layers`` are file-derived mappings from lowest to highest precedence
    (e.g. global config, project config, alias); only recognized
    file parameters are taken from them. ``supplied`` holds the runtime
    flags, which win over everything.
    """
    config = {name: copy.deepcopy(param.default) for name, param in GLOBAL_PARAMETERS.items()}
    for layer in layers:
        for key, value in (layer or {}).items():
            if is_file_parameter(key):
                config[key] = value
    config.update(supplied)
    config["disabled_commands"] = [str(c) for c in _arrayify(config.get("disabled_commands"))]
    return config
"""Execution context handed to command handlers."""

from dataclasses import dataclass, field


@dataclass
class Context:
    root: object
    command: object
    output: object
    runtime: dict = field(default_factory=dict)
    strict: bool = False
    config: object = None
    alias: str = None
"""appctl: a hierarchical command dispatcher."""

__version__ = "1.0.0"

PROGRAM_NAME = "appctl"
"""Writers for the different kinds of user-facing output."""

import os
import platform
import select
import stat
import sys
import time

RESET = "\033[0m"
COLORS = {
    "Error": "\033[1;31m",    # red
    "Warning": "\033[1;33m",  # yellow
    "Success": "\033[1;32m",  # green
    "Debug": "\033[1;34m",    # blue
}
BOX_COLOR = "\033[1;37;41m"   # white on red

# How long to wait for piped STDIN data that has not arrived yet.
STDIN_WAIT = 1.0

_TRUE = ("1", "true", "yes", "on", "always")
_FALSE = ("0", "false", "no", "off", "never")


def parse_color(value):
    """Normalise a ``color`` setting to ``True``, ``False`` or ``"auto"``."""
    if isinstance(value, bool):
        return value
    text = "" if value is None else str(value).strip().lower()
    if text in _TRUE:
        return True
    if text in _FALSE:
        return False
    return "auto"


def _isatty(stream):
    try:
        return bool(stream.isatty())
    except (AttributeError, ValueError, OSError):
        return False


def _stdin_ready(stream, timeout):
    """True when reading ``stream`` will not block indefinitely."""
    try:
        fd = stream.fileno()
        mode = os.fstat(fd).st_mode
    except (AttributeError, ValueError, OSError):
        return True  # in-memory stream
    if stat.S_ISREG(mode) or stat.S_ISCHR(mode):
        return True
    try:
        ready, _, _ = select.select([fd], [], [], timeout)
    except (OSError, ValueError):
        return True
    return bool(ready)


class Output:
    """Routes messages to STDOUT/STDERR and the log file.

    Honours ``--quiet``, ``--debug[=<group>]`` and ``--[no-]color``.
    """

    def __init__(self, quiet=False, debug=False, stdout=None, stderr=None, stdin=None,
                 color="auto", logger=None, start_time=None):
        self.quiet = quiet
        if debug == "":
            debug = True
        self.debug_enabled = bool(debug)
        self.debug_group = debug if isinstance(debug, str) else None
        self._stdout = stdout
        self._stderr = stderr
        self._stdin = stdin
        self._color = parse_color(color)
        self.logger = logger
        self.start_time = time.monotonic() if start_time is None else start_time

    @property
    def stdout(self):
        return self._stdout or sys.stdout

    @property
    def stderr(self):
        return self._stderr or sys.stderr

    @property
    def stdin(self):
        return self._stdin or sys.stdin

    # -- colors -----------------------------------------------------------

    def set_color(self, value):
        self._color = parse_color(value)

    @property
    def color(self):
        """Whether output is colorized (auto: STDOUT is a TTY, not Windows)."""
        if self._color == "auto":
            return _isatty(self.stdout) and platform.system() != "Windows"
        return self._color

    def _label(self, kind, label=None):
        label = label or f"{kind}:"
        return f"{COLORS[kind]}{label}{RESET}" if self.color else label

    # -- log file -----------------------------------------------------------

    def _log_file(self, text):
        if self.logger is not None:
            self.logger.write(text)

    def elapsed(self):
        return time.monotonic() - self.start_time

    # -- message categories ---------------------------------------------------

    def line(self, text=""):
        """Print a line on STDOUT unconditionally."""
        print(text, file=self.stdout)

    def log(self, text, sensitive=False):
        """Informational line on STDOUT unless --quiet; logged unless sensitive."""
        if not self.quiet:
            print(text, file=self.stdout)
        if not sensitive:
            self._log_file(text)

    def success(self, text):
        if not self.quiet:
            print(f"{self._label('Success')} {text}", file=self.stdout)

    def warning(self, text):
        if not self.quiet:
            print(f"{self._label('Warning')} {text}", file=self.stderr)
        self._log_file(f"Warning: {text}")

    def error(self, text, sensitive=False):
        print(f"{self._label('Error')} {text}", file=self.stderr)
        if not sensitive:
            self._log_file(f"Error: {text}")

    def error_multi_line(self, lines, sensitive=False):
        """Show an error in a highlighted box on STDERR."""
        lines = [str(line).replace("\t", "    ") for line in lines] or [""]
        lines = ["Error: " + lines[0]] + ["       " + line for line in lines[1:]]
        width = max(len(line) for line in lines)
        border = "+" + "-" * (width + 2) + "+"
        box = [border] + [f"| {line.ljust(width)} |" for line in lines] + [border]
        if self.color:
            box = [f"{BOX_COLOR}{row}{RESET}" for row in box]
        print("\n".join(box), file=self.stderr)
        if not sensitive:
            self._log_file("\n".join(lines))

    def debug(self, text, group=None):
        """Debug line with elapsed time; ``--debug=<group>`` filters by group."""
        if not self.debug_enabled:
            return
        if self.debug_group is not None and group != self.debug_group:
            return
        label = f"Debug ({group}):" if group else "Debug:"
        message = f"{text} ({self.elapsed():.3f}s)"
        print(f"{self._label('Debug', label)} {message}", file=self.stderr)
        self._log_file(f"{label} {message}")

    # -- user input -------------------------------------------------------------

    def prompt(self, question):
        """Show ``question``, read one line and return it trimmed and lowercased."""
        self.stdout.write(question)
        self.stdout.flush()
        try:
            answer = self.stdin.readline()
        except (AttributeError, OSError, ValueError):
            answer = ""
        return (answer or "").strip().lower()

    def confirm(self, question, assoc=None):
        """Ask ``question [y/n]``; ``--yes`` auto-confirms. Return True to proceed."""
        if assoc and assoc.get("yes"):
            return True
        if self.prompt(f"{question} [y/n] ") != "y":
            self.warning("Operation cancelled.")
            return False
        return True

    def read_stdin(self, timeout=STDIN_WAIT):
        """Return all piped STDIN content, or ``None`` if there is none."""
        stream = self.stdin
        if stream is None or _isatty(stream) or not _stdin_ready(stream, timeout):
            return None
        try:
            data = stream.read()
        except (OSError, ValueError):
            return None
        return data or None
"""Execution of a command on a remote endpoint (SSH, Docker, Vagrant)."""

import json
import os
import re
import shlex
import subprocess
import sys

from . import PROGRAM_NAME
from .arguments import END_OF_OPTIONS, is_assoc_token, parse_assoc_token
from .errors import AppctlError

SSH_PRE_CMD_ENV = "APPCTL_SSH_PRE_CMD"
SSH_BINARY_ENV = "APPCTL_SSH_BINARY"
CONNECTION_FAILED = 255

SSH_URL_RE = re.compile(
    r"^(?:(?P<scheme>docker|docker-compose|docker-compose-run|ssh|vagrant):(?://)?)?"
    r"(?:(?P<user>[^@:/]+)@)?"
    r"(?P<host>[^:/~]+)"
    r"(?::(?P<port>\d*))?"
    r"(?P<path>[/~].*)?$"
)


def parse_ssh_url(url):
    """Split ``[scheme:][user@]host[:port][path]`` into its components."""
    match = SSH_URL_RE.match(str(url).strip())
    if not match:
        raise AppctlError(f"Invalid SSH connection string '{url}'.")
    return {k: v for k, v in match.groupdict().items() if v}


def _strip_ssh_flags(argv):
    stripped = []
    end_of_options = False
    for token in argv:
        if token == END_OF_OPTIONS:
            end_of_options = True
        elif not end_of_options and is_assoc_token(token) and parse_assoc_token(token)[0] == "ssh":
            continue
        stripped.append(token)
    return stripped


def build_remote_command(argv, environ, alias=None, alias_params=None, path=None):
    """The shell command run on the remote side."""
    binary = environ.get(SSH_BINARY_ENV) or PROGRAM_NAME
    prefix = ""
    pre_cmd = (environ.get(SSH_PRE_CMD_ENV) or "").strip().rstrip(";").strip()
    if pre_cmd:
        prefix = pre_cmd + "; "
    words = []
    if alias:
        forwarded = {k: v for k, v in (alias_params or {}).items() if k != "ssh"}
        if forwarded:
            encoded = json.dumps({alias: forwarded}, separators=(",", ":"))
            prefix += f"APPCTL_RUNTIME_ALIAS={shlex.quote(encoded)} "
            words.append(alias)
    words.extend(_strip_ssh_flags(argv))
    if path:
        words.append(f"--path={path}")
    return prefix + " ".join([binary] + [shlex.quote(w) for w in words])


def build_transport(bits, remote_command, tty=False, proxyjump=None, key=None):
    """argv of the local process that carries ``remote_command``."""
    scheme = bits.get("scheme", "ssh")
    host = bits["host"]
    user = bits.get("user")
    if scheme == "docker":
        argv = ["docker", "exec"]
        if user:
            argv += ["--user", user]
        argv += ["-it" if tty else "-i", host, "sh", "-c", remote_command]
        return argv
    if scheme in ("docker-compose", "docker-compose-run"):
        argv = ["docker-compose", "exec" if scheme == "docker-compose" else "run"]
        if user:
            argv += ["--user", user]
        if not tty:
            argv.append("-T")
        if scheme == "docker-compose-run":
            argv.append("--rm")
        argv += [host, "sh", "-c", remote_command]
        return argv
    if scheme == "vagrant":
        return ["vagrant", "ssh", "-c", remote_command, host]
    argv = ["ssh", "-q"]
    if proxyjump:
        argv += ["-J", str(proxyjump)]
    if key:
        argv += ["-i", str(key)]
    if bits.get("port"):
        argv += ["-p", str(int(bits["port"]))]
    argv.append("-t" if tty else "-T")
    argv.append(f"{user}@{host}" if user else host)
    argv.append(remote_command)
    return argv


def _real_stream(stream, default):
    return stream is None or stream is default


def run_remote(ssh, argv, environ, output, alias=None, alias_params=None, skip_tty=False):
    """Run the command remotely and return its exit code."""
    bits = parse_ssh_url(ssh)
    alias_params = alias_params or {}
    remote_command = build_remote_command(argv, environ, alias, alias_params, bits.get("path"))
    passthrough = _real_stream(output.stdout, sys.stdout) and _real_stream(output.stderr, sys.stderr)
    tty = bool(passthrough and not skip_tty and sys.stdout.isatty() and sys.stdin.isatty())
    transport = build_transport(bits, remote_command, tty=tty,
                                proxyjump=alias_params.get("proxyjump"),
                                key=alias_params.get("key"))
    output.debug("Running SSH command: " + " ".join(shlex.quote(a) for a in transport))
    output.stdout.flush()
    output.stderr.flush()
    try:
        if passthrough:
            code = subprocess.run(transport, env=dict(environ)).returncode
        else:
            result = subprocess.run(transport, env=dict(environ), capture_output=True, text=True)
            output.stdout.write(result.stdout)
            output.stderr.write(result.stderr)
            code = result.returncode
    except OSError:
        code = CONNECTION_FAILED
    if code == CONNECTION_FAILED:
        raise AppctlError("Cannot connect over SSH using provided configuration.", CONNECTION_FAILED)
    return code

