"""Registration of commands into a tree rooted at the program command."""

from . import PROGRAM_NAME
from .command import Command


class CommandRegistry:
    """Builds the command tree from multi-level command paths."""

    def __init__(self, description=""):
        self.root = Command(PROGRAM_NAME, description=description)

    def add(self, path, handler=None, **attributes):
        """Register ``path`` (e.g. ``"site create"``) and return the command.

        Parent commands must be registered before their subcommands.
        """
        parts = path.split()
        if not parts:
            raise ValueError("A command path cannot be empty")
        parent = self.root
        for index, part in enumerate(parts[:-1]):
            child = parent.subcommands.get(part)
            if child is None:
                missing = " ".join(parts[: index + 1])
                raise ValueError(f"Parent command '{missing}' must be registered before '{path}'")
            parent = child
        return parent.add_subcommand(Command(parts[-1], handler=handler, **attributes))

    def get(self, path):
        node = self.root
        for part in path.split():
            node = node.subcommands[part]
        return node
"""The command tree node."""

from .errors import SynopsisError
from .synopsis import invalid_tokens, parse_synopsis


def sort_key(name):
    """Case-insensitive alphabetical ordering with a stable tie-break."""
    return (name.lower(), name)


class Command:
    """A node in the command tree.

    A command may have a handler, subcommands, or both. A command with
    subcommands but no handler only prints its usage when invoked.
    """

    def __init__(self, name, description="", synopsis="", handler=None,
                 alias=None, defaults=None, options=None, longdesc=""):
        self.name = name
        self.description = description
        self.synopsis = " ".join((synopsis or "").split())
        self.handler = handler
        self.alias = alias
        self.defaults = dict(defaults or {})
        self.options = dict(options or {})
        self.longdesc = longdesc
        self.parent = None
        self.subcommands = {}

        self.tokens = parse_synopsis(self.synopsis)
        bad = invalid_tokens(self.tokens)
        if bad:
            raise SynopsisError(
                f"The '{name}' command has an invalid synopsis part: {', '.join(bad)}"
            )

    # -- tree structure -------------------------------------------------

    def add_subcommand(self, command):
        for taken in self._taken_names():
            if taken in (command.name, command.alias):
                raise ValueError(
                    f"'{taken}' is already registered under '{self.full_name or 'appctl'}'"
                )
        command.parent = self
        self.subcommands[command.name] = command
        return command

    def _taken_names(self):
        for sub in self.subcommands.values():
            yield sub.name
            if sub.alias:
                yield sub.alias

    def find_subcommand(self, token):
        """Match a subcommand by canonical name first, then by alias."""
        if token in self.subcommands:
            return self.subcommands[token]
        for sub in self.subcommands.values():
            if sub.alias and sub.alias == token:
                return sub
        return None

    def sorted_subcommands(self):
        return [self.subcommands[k] for k in sorted(self.subcommands, key=sort_key)]

    def subcommand_names(self):
        return list(self.subcommands)

    # -- properties -----------------------------------------------------

    @property
    def is_root(self):
        return self.parent is None

    @property
    def has_subcommands(self):
        return bool(self.subcommands)

    @property
    def is_runnable(self):
        return self.handler is not None

    @property
    def path(self):
        """Canonical names from the top-level command down to this one."""
        parts = []
        node = self
        while node is not None and not node.is_root:
            parts.append(node.name)
            node = node.parent
        return list(reversed(parts))

    @property
    def full_name(self):
        return " ".join(self.path)

    def tokens_of_type(self, *types):
        return [t for t in self.tokens if t.type in types]

    def __repr__(self):
        return f"Command({self.full_name or '<root>'!r})"
"""Loading of global/project YAML config files and alias definitions."""

import json
import os
import re
from dataclasses import dataclass, field

import yaml

from .errors import AppctlError

CONFIG_PATH_ENV = "APPCTL_CONFIG_PATH"
ROOT_DIR_ENV = "APPCTL_ROOT_DIR"
PACKAGES_DIR_ENV = "APPCTL_PACKAGES_DIR"
RUNTIME_ALIAS_ENV = "APPCTL_RUNTIME_ALIAS"

PROJECT_CONFIG_FILES = ("appctl.local.yml", "appctl.yml")
ALIAS_RE = re.compile(r"^@[A-Za-z0-9_.\-]+$")
ALL_ALIAS = "@all"
META_KEY = "_"

# Keys the global config file must always define, with their defaults.
REQUIRED_GLOBAL_KEYS = (("locale", "en_US"), ("installer_version", "stable"))


def is_alias(name):
    return isinstance(name, str) and bool(ALIAS_RE.match(name))


def alias_sort_key(name):
    return (name.lower(), name)


# -- locations -----------------------------------------------------------


def root_dir(environ):
    value = environ.get(ROOT_DIR_ENV)
    if value:
        return value
    return os.path.join(os.path.expanduser("~"), ".appctl")


def global_config_path(environ):
    value = environ.get(CONFIG_PATH_ENV)
    if value:
        return value
    return os.path.join(root_dir(environ), "config", "config.yml")


def packages_dir(environ):
    value = environ.get(PACKAGES_DIR_ENV)
    if value:
        return value
    return os.path.join(root_dir(environ), "packages")


def find_project_config(cwd):
    """Search upward from ``cwd``; the first directory with a config wins."""
    directory = os.path.abspath(cwd)
    while True:
        for name in PROJECT_CONFIG_FILES:
            candidate = os.path.join(directory, name)
            if os.path.isfile(candidate):
                return candidate
        parent = os.path.dirname(directory)
        if parent == directory:
            return None
        directory = parent


# -- auto-creation ---------------------------------------------------------


def _read_mapping(path):
    with open(path, encoding="utf-8") as handle:
        text = handle.read()
    try:
        data = yaml.safe_load(text)
    except yaml.YAMLError as exc:
        raise AppctlError(f"Unable to parse the config file '{path}': {exc}") from exc
    if data is None:
        data = {}
    if not isinstance(data, dict):
        raise AppctlError(f"The config file '{path}' must contain a YAML mapping.")
    return data, text


def ensure_global_config(path, strict=True):
    """Add missing required keys to the global config file, creating it.

    Write failures raise :class:`AppctlError` unless ``strict`` is false.
    """
    try:
        if os.path.exists(path):
            data, text = _read_mapping(path)
        else:
            data, text = {}, ""
        missing = [(k, v) for k, v in REQUIRED_GLOBAL_KEYS if k not in data]
        if not missing:
            return
        if text and not text.endswith("\n"):
            text += "\n"
        text += "".join(f"{key}: {value}\n" for key, value in missing)
        directory = os.path.dirname(path)
        if directory:
            os.makedirs(directory, exist_ok=True)
        with open(path, "w", encoding="utf-8") as handle:
            handle.write(text)
    except OSError as exc:
        if strict:
            reason = exc.strerror or str(exc)
            raise AppctlError(f"Unable to write the config file '{path}': {reason}.") from exc


# -- YAML loading with inheritance -------------------------------------------


def _merge(base, override, append_arrays):
    """Overlay ``override`` on ``base``; nested mappings merge recursively."""
    if isinstance(base, dict) and isinstance(override, dict):
        merged = dict(base)
        for key, value in override.items():
            merged[key] = _merge(base[key], value, append_arrays) if key in base else value
        return merged
    if append_arrays and isinstance(base, list) and isinstance(override, list):
        return base + override
    return override


def _absolutize_alias_paths(data, directory):
    for key, value in data.items():
        if is_alias(key) and isinstance(value, dict):
            path = value.get("path")
            if isinstance(path, str) and path and "ssh" not in value:
                value["path"] = os.path.normpath(os.path.join(directory, os.path.expanduser(path)))


def load_config_file(path, accumulated=None, _seen=None):
    """Merge the YAML file at ``path`` (and its ancestors) over ``accumulated``."""
    accumulated = dict(accumulated or {})
    if not path:
        return accumulated
    path = os.path.abspath(path)
    seen = set(_seen or ())
    if path in seen or not os.path.isfile(path):
        return accumulated
    seen.add(path)
    try:
        data, _ = _read_mapping(path)
    except OSError:
        return accumulated
    directory = os.path.dirname(path)
    meta = data.pop(META_KEY, None)
    meta = meta if isinstance(meta, dict) else {}
    inherit = meta.get("inherit")
    if isinstance(inherit, str) and inherit:
        base = os.path.join(directory, os.path.expanduser(inherit))
        accumulated = load_config_file(base, accumulated, seen)
    _absolutize_alias_paths(data, directory)
    return _merge(accumulated, data, meta.get("merge") is True)


# -- aliases -------------------------------------------------------------------


def runtime_aliases(environ, cwd):
    raw = environ.get(RUNTIME_ALIAS_ENV)
    if not raw:
        return {}
    try:
        decoded = json.loads(raw)
    except ValueError:
        return {}
    if not isinstance(decoded, dict):
        return {}
    aliases = {k: v for k, v in decoded.items() if is_alias(k)}
    _absolutize_alias_paths(aliases, cwd)
    return aliases


def collect_aliases(config, extra=None):
    """Return ``{name: definition}``, registering ``@all`` when needed.

    A definition is either a mapping of connection parameters or a list
    of alias names (a group).
    """
    aliases = {}
    for key, value in list(config.items()) + list((extra or {}).items()):
        if not is_alias(key):
            continue
        if isinstance(value, list):
            aliases[key] = [str(v) for v in value]
        elif isinstance(value, dict):
            aliases[key] = dict(value)
        elif value is None:
            aliases[key] = {}
        else:
            aliases[key] = value
    if aliases and ALL_ALIAS not in aliases:
        aliases[ALL_ALIAS] = None  # implicit: every registered alias
    return aliases


# -- entry point ---------------------------------------------------------------


@dataclass
class LoadedConfig:
    global_path: str = None
    project_path: str = None
    global_config: dict = field(default_factory=dict)
    merged: dict = field(default_factory=dict)
    aliases: dict = field(default_factory=dict)
    packages_dir: str = None


def load(environ, cwd=None):
    cwd = cwd or os.getcwd()
    global_path = global_config_path(environ)
    explicit = bool(environ.get(CONFIG_PATH_ENV) or environ.get(ROOT_DIR_ENV))
    ensure_global_config(global_path, strict=explicit)
    global_config = load_config_file(global_path)
    project_path = find_project_config(cwd)
    if project_path and os.path.abspath(project_path) == os.path.abspath(global_path):
        project_path = None
    merged = load_config_file(project_path, global_config)
    return LoadedConfig(
        global_path=global_path,
        project_path=project_path,
        global_config=global_config,
        merged=merged,
        aliases=collect_aliases(merged, runtime_aliases(environ, cwd)),
        packages_dir=packages_dir(environ),
    )
"""Shared behaviour for plugin and theme management commands."""

from ..errors import AppctlError
from ._listing import render_list

LIST_FIELDS = ["name", "status", "update", "version"]


class ExtensionCatalog:
    """A simulated collection of installed plugins or themes."""

    def __init__(self, noun, items):
        self.noun = noun
        self.items = items

    def find(self, name):
        return next((i for i in self.items if i["name"] == name), None)

    def targets(self, args, assoc):
        """Resolve the named items, or every item with ``--all``."""
        if assoc.get("all"):
            return [i["name"] for i in self.items]
        if not args:
            raise AppctlError(f"Please specify one or more {self.noun}s, or use --all.")
        return list(args)

    def each_installed(self, ctx, names):
        for name in names:
            if self.find(name) is None:
                ctx.output.warning(f"The '{name}' {self.noun} could not be found.")
            else:
                yield name

    # -- handlers -------------------------------------------------------

    def list(self, ctx, args, assoc):
        render_list(ctx, self.items, assoc, LIST_FIELDS, LIST_FIELDS + ["title"], id_field="name")

    def status(self, ctx, args, assoc):
        if args:
            item = self.find(args[0])
            if item is None:
                raise AppctlError(f"The '{args[0]}' {self.noun} could not be found.")
            ctx.output.line(f"{self.noun.capitalize()} {item['name']} details:")
            ctx.output.line(f"    Name: {item['title']}")
            ctx.output.line(f"    Status: {item['status'].capitalize()}")
            ctx.output.line(f"    Version: {item['version']}")
            return
        ctx.output.line(f"{len(self.items)} installed {self.noun}s:")
        for item in self.items:
            marker = "A" if item["status"] == "active" else "I"
            ctx.output.line(f"  {marker} {item['name']} {item['version']}")

    def install(self, ctx, args, assoc):
        for name in args:
            if self.find(name) and not assoc.get("force"):
                ctx.output.warning(f"{name}: {self.noun.capitalize()} already installed.")
                continue
            ctx.output.log(f"Installing {name} ({assoc['version']})...")
            if assoc.get("activate"):
                ctx.output.log(f"Activating '{name}'...")
        ctx.output.success(f"Installed {len(args)} of {len(args)} {self.noun}s.")

    def delete(self, ctx, args, assoc):
        names = self.targets(args, assoc)
        deleted = list(self.each_installed(ctx, names))
        for name in deleted:
            ctx.output.log(f"Deleted '{name}' {self.noun}.")
        self.summary(ctx, "Deleted", len(deleted), len(names))

    def update(self, ctx, args, assoc):
        names = self.targets(args, assoc)
        found = list(self.each_installed(ctx, names))
        if assoc.get("dry-run"):
            ctx.output.log(f"Available {self.noun} updates: {', '.join(found) or 'none'}")
            return
        self.summary(ctx, "Updated", len(found), len(names))

    def summary(self, ctx, verb, done, total):
        if done == total:
            ctx.output.success(f"{verb} {done} of {total} {self.noun}s.")
        else:
            raise AppctlError(f"Only {verb.lower()} {done} of {total} {self.noun}s.")
"""End-to-end tests running appctl.py as a subprocess."""

import os
import re
import subprocess
import sys
import unittest

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
SCRIPT = os.path.join(ROOT, "appctl.py")


def run(*args, strict=False):
    env = {k: v for k, v in os.environ.items() if k != "APPCTL_STRICT_ARGS_MODE"}
    if strict:
        env["APPCTL_STRICT_ARGS_MODE"] = "1"
    return subprocess.run([sys.executable, SCRIPT, *args], capture_output=True, text=True,
                          env=env, cwd=ROOT)


class CliTest(unittest.TestCase):
    def test_no_arguments_lists_commands_sorted_and_aligned(self):
        result = run()
        self.assertEqual(result.returncode, 0)
        rows = [m for m in re.finditer(r"^  (\S+)( +)(\S.*)$", result.stdout, re.M)]
        names = [m.group(1) for m in rows]
        self.assertIn("site", names)
        self.assertEqual(names, sorted(names, key=str.lower))
        columns = {len(m.group(1)) + len(m.group(2)) for m in rows}
        self.assertEqual(len(columns), 1)

    def test_unknown_command(self):
        result = run("sitee")
        self.assertEqual(result.returncode, 1)
        self.assertEqual(result.stderr, (
            "Error: 'sitee' is not a registered appctl command. "
            "See 'appctl help' for available commands.\nDid you mean 'site'?\n"))
        self.assertEqual(result.stdout, "")

    def test_unknown_command_without_suggestion(self):
        result = run("qqqqqq")
        self.assertEqual(result.returncode, 1)
        self.assertNotIn("Did you mean", result.stderr)

    def test_unknown_subcommand(self):
        result = run("site", "craete")
        self.assertEqual(result.returncode, 1)
        self.assertEqual(result.stderr, (
            "Error: 'craete' is not a registered subcommand of 'site'. "
            "See 'appctl help site' for available subcommands.\nDid you mean 'create'?\n"))

    def test_synonym_suggestion(self):
        self.assertIn("Did you mean 'create'?", run("site", "new").stderr)

    def test_alias_wins_over_synonym(self):
        result = run("user", "remove", "2")
        self.assertEqual(result.returncode, 0)
        self.assertNotIn("Did you mean", result.stderr)
        self.assertIn("Removed user 2", result.stdout)

    def test_parent_without_handler_prints_usage(self):
        result = run("site")
        self.assertEqual(result.returncode, 0)
        self.assertIn("usage: appctl site activate", result.stdout)
        self.assertIn("   or: appctl site create", result.stdout)

    def test_missing_positional_prints_usage(self):
        result = run("site", "create")
        self.assertEqual(result.returncode, 1)
        self.assertTrue(result.stdout.startswith("usage: appctl site create <site-name>"))

    def test_too_many_positionals(self):
        result = run("site", "create", "a", "b")
        self.assertEqual(result.returncode, 1)
        self.assertEqual(result.stderr, "Error: Too many positional arguments: b\n")

    def test_missing_required_assoc(self):
        result = run("config", "create", "--dbname=x", "--dbuser=")
        self.assertEqual(result.returncode, 1)
        self.assertEqual(result.stderr, "Error: Parameter errors:\n missing --dbuser parameter\n")

    def test_unknown_assoc_with_suggestion(self):
        result = run("site", "create", "x", "--typ=a", "--bogus")
        self.assertEqual(result.returncode, 1)
        self.assertEqual(result.stderr, (
            "Error: Parameter errors:\n unknown --typ parameter\nDid you mean '--type'?\n"
            " unknown --bogus parameter\n"))

    def test_defaults_applied(self):
        result = run("site", "create", "x")
        self.assertEqual(result.returncode, 0)
        self.assertIn("type: standard", result.stdout)

    def test_no_prefix_sets_false(self):
        self.assertIn("visibility: public", run("site", "create", "x", "--no-private").stdout)
        self.assertIn("visibility: private", run("site", "create", "x", "--private").stdout)

    def test_help_rewrite(self):
        self.assertEqual(run("site", "create", "--help").stdout, run("help", "site", "create").stdout)
        self.assertIn("SYNOPSIS", run("site", "create", "--help").stdout)

    def test_version_rewrite(self):
        result = run("--version")
        self.assertEqual((result.returncode, result.stdout), (0, run("cli", "version").stdout))

    def test_strict_mode(self):
        self.assertEqual(run("site", "create", "x", "--url=a").returncode, 0)
        strict = run("site", "create", "x", "--url=a", strict=True)
        self.assertEqual(strict.returncode, 1)
        self.assertIn("unknown --url parameter", strict.stderr)
        self.assertEqual(run("--url=a", "site", "create", "x", strict=True).returncode, 0)


